CREATE TABLE finops_dcf_snapshots(generation_id text PRIMARY KEY CHECK(generation_id~'^dcg_[a-f0-9]{64}$'),org_id text NOT NULL REFERENCES organizations(id)ON DELETE CASCADE,customer_id text NOT NULL REFERENCES customers(id)ON DELETE CASCADE,connection_id text NOT NULL REFERENCES aws_connections(id)ON DELETE CASCADE,capture_id text NOT NULL,complete boolean NOT NULL,provider_access text NOT NULL,content_sha256 text NOT NULL CHECK(content_sha256~'^[a-f0-9]{64}$'),snapshot_json text NOT NULL CHECK(octet_length(snapshot_json)BETWEEN 2 AND 67108864),completed_at text NOT NULL,module_count bigint NOT NULL,execution_count bigint NOT NULL,created_at bigint NOT NULL,UNIQUE(org_id,customer_id,connection_id,capture_id));CREATE INDEX finops_dcf_history_idx ON finops_dcf_snapshots(org_id,customer_id,connection_id,completed_at DESC);CREATE TABLE finops_dcf_heads(org_id text NOT NULL,customer_id text NOT NULL,connection_id text NOT NULL,active_generation_id text NOT NULL UNIQUE REFERENCES finops_dcf_snapshots(generation_id),advanced_at bigint NOT NULL,PRIMARY KEY(org_id,customer_id,connection_id));
CREATE OR REPLACE FUNCTION finops_dcf_guard()RETURNS trigger AS $$BEGIN RAISE EXCEPTION 'FINOPS_DCF_SNAPSHOT_IMMUTABLE';END;$$LANGUAGE plpgsql;CREATE TRIGGER finops_dcf_snapshots_update_guard BEFORE UPDATE ON finops_dcf_snapshots FOR EACH ROW EXECUTE FUNCTION finops_dcf_guard();CREATE TRIGGER finops_dcf_snapshots_delete_guard BEFORE DELETE ON finops_dcf_snapshots FOR EACH ROW EXECUTE FUNCTION finops_dcf_guard();
CREATE OR REPLACE FUNCTION finops_dcf_head_guard()RETURNS trigger AS $$DECLARE c finops_dcf_snapshots%ROWTYPE;DECLARE a finops_dcf_snapshots%ROWTYPE;BEGIN SELECT * INTO c FROM finops_dcf_snapshots WHERE generation_id=NEW.active_generation_id;IF c.generation_id IS NULL OR NOT c.complete OR c.org_id<>NEW.org_id OR c.customer_id<>NEW.customer_id OR c.connection_id<>NEW.connection_id THEN RAISE EXCEPTION 'FINOPS_DCF_HEAD_REJECTED';END IF;IF TG_OP='UPDATE'THEN SELECT * INTO a FROM finops_dcf_snapshots WHERE generation_id=OLD.active_generation_id;IF c.completed_at<=a.completed_at THEN RAISE EXCEPTION 'FINOPS_DCF_HEAD_REJECTED';END IF;END IF;RETURN NEW;END;$$LANGUAGE plpgsql;CREATE TRIGGER finops_dcf_heads_write_guard BEFORE INSERT OR UPDATE ON finops_dcf_heads FOR EACH ROW EXECUTE FUNCTION finops_dcf_head_guard();REVOKE ALL ON finops_dcf_snapshots FROM PUBLIC;REVOKE ALL ON finops_dcf_heads FROM PUBLIC;
